    const _mcCo = (_mcPlan.length === 1 && _mcPlan[0].company_name) ? `*${_mcPlan[0].company_name}* ` : '';
    const _mcPhrase = `Would you like me to escalate to ${_mcCo}${_mcTeam} team?`;   // FROZEN prefix wording — do not reword
