  }
  // #12: when the customer typed a code that matches EXACTLY, that code must be the
  // representative. `_compat` order is arbitrary, so codes[0] could name a sibling variant
  // (SRTSH1040-T for a typed SRTSH1040), reading as if we looked up a different product.
  const _tokSet = new Set(tokens.map(t => String(t ?? '').trim().toLowerCase()).filter(Boolean));
  // mc-label: the label may now carry a " (Company)" suffix, which no typed token will ever match.
  // Strip it for the comparison ONLY in the multi-company case — an order label is legitimately
  // `DO123 (Acme Sdn Bhd)`, and stripping unconditionally would start reordering single-company
  // types that do not reorder today.
  const _bareLabel = (l) => _multiCo ? String(l).replace(/\s+\([^)]*\)$/, '') : String(l);
  for (const arr of _byType.values()) {
    const i = arr.findIndex(l => _tokSet.has(_bareLabel(l).trim().toLowerCase()));
    if (i > 0) arr.unshift(arr.splice(i, 1)[0]);
  }
  // ── entitlement miss ≠ data miss ─────────────────────────────────────────
  // "Here's what you want: • promotion: X … But no promotion matched these." names a promotion
  // and then denies it in the same breath. Measured (exec 11917052): the resolver DID resolve
  // `SORENTO PP PROMO COMBINE_29072026.pdf` this turn via promotion_membership, display.is_active
  // TRUE, display.products ["SRTWB247"] — no stale carry. The contact's entitlement is
  // Aggregate.name = ["End User"], get-results applied it, and the Office-only promo came back
  // empty. Every fact needed to say so was already on the wire; only the sentence was wrong.
  //
  // Fires ONLY when a promotion was genuinely resolved and nothing came back. A turn that
  // resolved no promotion at all is a real data miss and keeps the original wording (B7), and an
  // INACTIVE promotion has ended rather than being withheld (B8) — blaming access there would be
  // a second false statement, not a fix for the first.
  const _entitlementMiss = (() => {
    if (q.domain_hint !== 'promotion') return null;
    const _promoMatches = [];
    const _push = (arr) => { for (const m of (arr || [])) if (m && m.entity_type === 'promotion') _promoMatches.push(m); };
    _push(r?.intersection);
    _push(r?.by_entity_type?.promotion);
    for (const res of (r?.resolutions || [])) _push(res?.matches);
    if (!_promoMatches.length) return null;
    const _seen = new Set(); const _uniq = [];
    for (const m of _promoMatches) {
      const k = m.uuid || m.canonical_code;
      if (!k || _seen.has(k)) continue;
      _seen.add(k); _uniq.push(m);
    }
    const _named = _uniq.map(m => (m.display && m.display.description) || null).filter(Boolean);
    if (!_named.length) return null;
    const _label = _named[0] + (_named.length > 1 ? ` and ${_named.length - 1} other${_named.length > 2 ? 's' : ''}` : '');
    const _anyActive = _uniq.some(m => m.display && m.display.is_active !== false);
    if (!_anyActive) {
      return `${_label} has ended, so there is nothing to send. Would you like me to escalate to ${team} team?`;
    }
    // Entitlement comes from the CRM read, not from anything the customer said. Absent ⇒ do not
    // invent a level (B9): say it is unavailable to them without naming one.
    let _levels = [];
    try {
      const _agg = $('Aggregate');
      if (_agg.isExecuted) _levels = (_agg.first().json.name || []).map(x => String(x || '').trim()).filter(Boolean);
    } catch (e) { _levels = []; }
    const _at = _levels.length ? ` at your access level (${_levels.join(', ')})` : ' to you';
    return `${_label} is not available${_at}. Would you like me to escalate to ${team} team?`;
  })();

  const _foundLines = [];
  for (const [et, codes] of _byType) {
    // one representative per type + count; true ambiguity is handled by the gate (did-you-mean).
    // FIX 1 (review 2, 2026-08-17). The cap is over DISTINCT CODES, not over labels. My first
    // version skipped it entirely whenever `_multiCo`, on the reasoning that the extra entries are
    // the same code in another company — true for ONE code, false for the turn: a turn that
    // resolved eight distinct products in a multi-company set dumped all eight into the WhatsApp
    // reply. The cap is not incidental, it is what keeps this line a summary.
    // So: group the type's labels by their BARE code (insertion order preserved, so the
    // typed-code-first reorder above still chooses the representative), render the representative
    // group IN FULL — naming its company variants is the entire point of the qualification — and
    // count the remaining DISTINCT CODES. Single-company is byte-identical: `_bareLabel` is the
    // identity there, so every label is its own group and this collapses to `codes[0]` + (+N).
    const _order = [];
    const _byCode = new Map();
    for (const l of codes) {
      const bare = _bareLabel(l);
      if (!_byCode.has(bare)) { _byCode.set(bare, []); _order.push(bare); }
      _byCode.get(bare).push(l);
    }
    const extra = _order.length > 1 ? ` (+${_order.length - 1} more)` : '';
    _foundLines.push(`• ${et}: ${_byCode.get(_order[0]).join(', ')}${extra}`);
  }
  _found_summary = _foundLines.join('\n');   // datemiss-summary: reused by build-suggest-offer
  // tokens the user gave that resolved to NOTHING (exclude those that resolved via fallback tiers)
  const _notFoundRaw = unresolved.filter(t => !_resolvedToks.has(normRaw(t)));
  const _useBreakdown = _foundLines.length > 0;
  // notFoundRaw override lets a branch fold some unresolved tokens into the searched noun
  // instead of listing them as "couldn't find" (e.g. attachment qualifiers like "SPAN").
  // mc-label: state the SEARCH SCOPE, so "nothing matched" cannot be read as "nothing matched in
  // the one company you were thinking of". Empty on a single-company turn, which keeps the
  // sentence byte-identical there. `_entitlementMiss` deliberately does not take it — that arm is
  // about a promotion being withheld from this contact, not about where we looked.
  const _coSuffix = _multiCo ? ` — checked in ${_andList(_searchedCos)}` : '';
  const buildBreakdownMsg = (domainWord, notFoundRaw) => {
    const nf = (notFoundRaw ?? _notFoundRaw).map(t => `"${t}"`);
    const parts = [];
    if (_foundLines.length) parts.push(`Here's what you want:\n${_foundLines.join('\n')}`);
    if (nf.length) parts.push(`Couldn't find: ${nf.join(', ')}.`);
    parts.push(_entitlementMiss
      || `But no${active_inactive} ${domainWord}${dateRange}${access} matched these${_coSuffix}. Would you like me to escalate to ${team} team?`);
    return parts.join('\n\n');
  };

  // vague-token clarify: among UNRESOLVED tokens only, map each back to a reformulator
  // entity by raw and read its `confident` flag. ANY confident:false => vague mash, not a
  // clear-but-missing record => CLARIFY (no escalate offer). Default-true: only === false fires.
  const vagueUnresolved = unresolved.filter(t => byRaw.get(normRaw(t))?.confident === false);

  if (vagueUnresolved.length > 0) {
    is_clarification = true;                       // escalate-catalog: is_escalate_offer = !is_clarification = false
    const labels = humanList(allowedTypes);        // ALLOWED[domain] = gate_debug.allowed_lookup
    const captured = vagueUnresolved.join(', ');
    // partial-aware: name what DID resolve (entities not in unresolved), excluding the vague blob(s).
    const unresolvedSet = new Set(unresolved.map(normRaw));
    const resolvedEnts = allEnts.filter(e => e && e.raw && !unresolvedSet.has(normRaw(e.raw)));
    const resolvedSummary = resolvedEnts
      .map(e => `${e.hint || 'item'} ${e.raw}`.trim())
      .filter(Boolean)
      .join(', ');
    if (resolvedSummary) {
      escalate_message =
        `I understood ${resolvedSummary}, but couldn't make out "${captured}" — ` +
        `is that a ${labels}? Please label it, e.g. customer <name>, product <code>.`;
    } else {
      escalate_message =
        `I captured "${captured}" but couldn't tell which part is which. ` +
        `For a ${q.domain_hint} enquiry, please give me a labeled specific — e.g. ${labels}.`;
    }
  } else {
  const require_specific = gate.require_specific
  if (require_specific) {
    escalate_message = gate.gate_clarification
  } else if (q.domain_hint === 'product_attachment') {
    // FIX B: natural, parser-driven phrasing — never leak the 'product_attachment' literal.
    const ents = Array.isArray(q?.entities) ? q.entities : [];
    const productRaws = ents.filter(e => e.hint === 'product').map(e => e.raw).filter(Boolean);
    const attachRaws  = ents.filter(e => e.hint === 'attachment_type').map(e => e.raw).filter(Boolean);
    const attachEnt   = ents.find(e => e.hint === 'attachment_type');
    if (_useBreakdown) {
      // combine the attachment-type qualifiers into ONE searched noun ("SPAN certificate")
      // and fold those qualifiers OUT of the "couldn't find" list (don't double-name them).
      const attachNoun = attachRaws.length ? attachRaws.join(' ') : (attachEnt?.raw || 'attachment');
      const attachSet  = new Set(attachRaws.map(normRaw));
      const nfRaw      = _notFoundRaw.filter(t => !attachSet.has(normRaw(t)));
      escalate_message = buildBreakdownMsg(attachNoun, nfRaw);
    } else {
      const prodText = productRaws.length ? `product ${productRaws.join(' and ')}` : '';
      let subject;
      if (attachEnt?.raw && prodText)      subject = `a ${attachEnt.raw} for ${prodText}`;
      else if (attachEnt?.raw)             subject = `a ${attachEnt.raw}`;
      else if (prodText)                   subject = `attachments for ${prodText}`;
      else                                 subject = requested || 'the requested item';   // fall back to the old token text
      escalate_message =
        `Could not find${active_inactive} ${subject}${dateRange}${access}. ` +
        `Would you like me to escalate to ${team} team?`;
    }
  } else {
    // status-filter-aware: a SPECIFIC order/customer_order resolved (the DO exists) but the
    // delivered/outstanding filter returned nothing => the order isn't a miss, it's just not in
    // that status. Say so, using the resolved match's own status/dates.
    const _orderMatch = _allMatches.find(m => m && _compatUuids.has(m.uuid) && _ORDER_TYPES.has(m.entity_type));
    if (_orderMatch && (q.order_status === 'delivered' || q.order_status === 'outstanding')) {
      const d = _orderMatch.display || {};
      const label = `${_orderMatch.canonical_code}${d.customer_name ? ` (${d.customer_name})` : ''}`;
      if (q.order_status === 'delivered') {
        const eta = d.estimated_delivery_date ? ` (estimated delivery ${d.estimated_delivery_date})` : '';
        const st  = d.status ? ` — current status: ${d.status}` : '';
        escalate_message =
          `Order ${label} hasn't been delivered yet${st}. ` +
          `Would you like me to escalate to ${team} team?`;
      } else {
        escalate_message =
          `Order ${label} has no outstanding items — it looks already delivered or closed. ` +
          `Would you like me to escalate to ${team} team?`;
      }
    } else if (_useBreakdown) {
      escalate_message = buildBreakdownMsg(`${_statusLabel}${q.domain_hint}`);
    } else if (_notFoundRaw.length && !_foundLines.length) {
      // NOTHING resolved. "Could not find promotion for stwc26" states that promotions were
      // searched and none matched — they were not. If3 dead-ends on the no-compatible-entity
      // branch and `Call 'sub-get-results'` never runs (verified, execs 12069620 / 12069702:
      // tool-filter, validator and the sub-call are all absent from runData). Saying we searched
      // sends the customer off correcting the wrong thing — retyping the domain rather than the
      // code they mistyped.
      // Phrasing is buildBreakdownMsg's, verbatim, so the zero-resolution and partial-resolution
      // misses read identically; the did-you-mean variant ("Couldn't find \"x\". Did you mean...")
      // still overrides this whenever the resolver returns alternatives.
      // Domain-agnostic ON PURPOSE: this node serves promotion, inventory and incoming alike.
      escalate_message =
      `Couldn't find: ${_notFoundRaw.map(t => `"${t}"`).join(', ')}. ` +
      `Would you like me to escalate to ${team} team?`;
    } else {
      const _forRequested = requested ? ` for ${requested}` : '';
      escalate_message =
      `Could not find${active_inactive} ${_statusLabel}${q.domain_hint}${_forRequested}${dateRange}${access}. ` +
      `Would you like me to escalate to ${team} team?`;
    }
  }
  }
}

// Q23: the customer named an access level they do not hold. The gate detects it; say so here
// too, or an entitlement problem reads as an ordinary "couldn't find it".
if (gate && gate.access_notice && escalate_message) {
  escalate_message = `${gate.access_notice}\n\n${escalate_message}`;
}

const out = $input.first().json;
out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
out.found_summary = _found_summary;   // datemiss-summary: resolved-entity bullets for the date arm
return out;

const j = $input.first().json;
const names = Array.isArray(j.name) ? j.name : [];
const q = $('Call \'sub-query-reformulator\'').first().json.output ?? {};
const domain = q.domain_hint || 'this enquiry';

// optional: friendlier labels than the raw domain_hint
const LABELS = {
  promotion: 'promotions',
  master_products: 'product information',
  product_attachment: 'product attachments',
  inventory: 'stock',
  order: 'orders',
  incoming: 'incoming stock',
  forms: 'forms',
  portal_link: 'this request',
};
const domainLabel = LABELS[q.domain_hint] || domain;

let escalate_message;
let is_clarification = false;

const out = j;

// ── tier-only access ask (access-tier-ask-plan.md D1/D3) ─────────────────────
// Reached on If4 FALSE: either the contact has NO access levels (names empty — keep the
// original message), or tier-gate decided the tier is unresolvable (multi-tier contact,
// nothing stated) and the customer must pick. The ask is a NUMBERED TYPED LIST — never
// WhatsApp quick-reply buttons (D3) — offering ONLY the tiers this contact actually holds
// (a 2-tier contact sees 2 options, renumbered). The roster is persisted downstream by
// compile-current-state (selection_context 'tier_offer'), and the parser fork resolves a
// numbered/tier-word reply to TIER TOKENS against it — never to entities.
const TIER_DISPLAY = { office: 'Office', dealer: 'Dealer', end_user: 'End user' };
const ASK_ORDER = ['office', 'dealer', 'end_user'];
const held = ASK_ORDER.filter(t => (Array.isArray(j.entitled_tiers) ? j.entitled_tiers : []).includes(t));

if (names.length === 0) {
  escalate_message = `You have no access levels configured to get ${domainLabel}.`;
} else if (held.length === 0) {
  // entitlement holds no mappable tier — cannot render a tier ask; fall back to the legacy
  // compound prompt rather than an empty numbered list. (tier-gate proceeds in this case,
  // so this branch is defensive only.)
  escalate_message =
    `Please specify which access level you'd like to use for ${domainLabel}:`;
  is_clarification = true;
} else {
  // D14 availability annotation. Style matches the incoming-stock picker
  // ("1. CODE - has incoming"), so a tier list reads like every other picker in the system.
  // A plain hyphen, not an em dash (user directive 2026-08-11: no em dashes in customer copy).
  // NOTE the incoming picker still renders an em dash; sweeping it touches another suite's
  // frozen baselines, so it is flagged rather than changed here.
  // `tier_availability` null means "not determined" -> render exactly as before, no annotation.
  // The all-empty case never reaches this node: `if-tier-has-any` routes it down the answer lane
  // instead, so the customer gets the real not-found + did-you-mean rather than a list of
  // options that all say "no promotion".
  const _avail = (() => {
    try {
      return $('tier-probe-collect').isExecuted
        ? ($('tier-probe-collect').first().json.tier_availability || null) : null;
    } catch (e) { return null; }
  })();
  // D16: name the thing being asked about, so "Which access level do you need?" cannot read as a
  // question about nothing. The rule is promo-picker's scope echo, reused verbatim so the ask and
  // the answer that follows it can never disagree: echo entity.raw (what the customer TYPED) and
  // never a canonical code — "6047" resolves to TWO products, so naming one would tell the customer
  // we searched something they did not ask for. Max 3 tokens; past 60 chars the echo is DROPPED
  // rather than truncated, because a half-printed promotion name reads like a different promotion.
  const _scopeLabel = (() => {
    const raws = [];
    for (const e of (Array.isArray(q.entities) ? q.entities : [])) {
      const v = String((e && e.raw) || '').trim();
      if (v && !raws.some(x => x.toLowerCase() === v.toLowerCase())) raws.push(v);
    }
    const str = raws.slice(0, 3).join(', ');
    return str.length > 60 ? '' : str;
  })();
  const _scopeSuffix = _scopeLabel ? ` for ${_scopeLabel}` : '';
  const lines = held.map((t, i) => {
    const mark = _avail ? (_avail[t] ? ' - has promotion' : ' - no promotion') : '';
    return `${i + 1}. ${TIER_DISPLAY[t]}${mark}`;
  }).join('\n');
  escalate_message =
    `Which access level do you need${_scopeSuffix}?\n${lines}\nReply with the number(s), e.g. "1", "1 and 2", or "all".`;
  is_clarification = true;
  out.tier_offer = true;
  out.tier_last_result_set = held.map((t, i) => ({
    idx: i + 1, label: TIER_DISPLAY[t], value: t, tier: t,
    uuid: null, entity_type: 'access_tier', product: null, filename: null,
  }));
}

out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
// D3: the ask is a numbered TYPED list — never quick-reply buttons.
out.quick_reply = '';
return out;

// ── ONE tool per turn (tool-loop-removal, 2026-08-03) ───────────────────────────
// Emits EXACTLY ONE item, always. The per-tool splitOut + splitInBatches fan-out
// that used to sit between this node and get-results is deleted, so nothing
// downstream serialises multiple items any more: two items here would run the whole
// get-results → compile → send chain twice, i.e. two WhatsApp messages to one
// customer. `return [{ json: … }]` is a one-element literal, so the arity is
// structural — it does not depend on how many embeddings the tool registry holds.
//
// Selection = highest `similarity`, tiebreak `name` ASC (deterministic for
// golden-master). Explicitly NOT the first array element: sub-get-rag's final Code
// node collapses source_id → name and does `map[name].similarity += …`, so the SQL
// best-first insertion order is not provably the maximum once any tool has two
// source_ids.
const rag = $("Execute 'sub-get-rag'").first().json || {};
const raw_tools = Array.isArray(rag.tools) ? rag.tools : [];

// Tolerant read of the entity gate. The previous body did
// `entities.some(e => e.entity_type === 'product')` and THREW when
// compatible_entities was undefined; that throw is deliberately removed here and
// the value is recorded rather than dropped (the old `hasProduct` was dead code).
let has_product = null;
try {
  const entities = $('disallowed-entity-gate').first().json.compatible_entities;
  has_product = Array.isArray(entities)
    ? entities.some(e => e && e.entity_type === 'product')
    : null;
} catch (e) {
  has_product = null;
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const score = (t) => {
  const n = Number(t && t.similarity);
  return Number.isFinite(n) ? n : -Infinity;
};
const label = (t) => String((t && t.name) ?? '');
const sorted = raw_tools
  .slice()
  .sort((a, b) => cmp(score(b), score(a)) || cmp(label(a), label(b)));

const best = sorted[0];
// 0 tools in → 0 items out. Preserves today's behaviour exactly (the old splitOut
// emitted 0 items on an empty tools[] and the loop body never ran). Pre-existing
// dead-end, backlog in UAC §TL-EMPTY — deliberately NOT turned into a throw here.
if (!best) return [];

return [
  {
    json: {
      ...best,
      _tool_pick: {
        chosen: label(best),
        rejected: sorted.slice(1).map(t => ({ name: label(t), similarity: score(t) })),
        count: raw_tools.length,
        has_product,
      },
    },
  },
];

// ── escalate-catalog ────────────────────────────────
// Single source of truth for escalation/error messages + their behavior flags.
// Each upstream branch sets ONE field `branch_kind`; this node maps it to the
// message + flags that compile-current-state used to derive via a 7-arm ladder.
// Dynamic kinds (not_found, access_choice) pull their message by reference from
// the upstream Code node that computed it.
const qf  = $('Call \'sub-query-reformulator\'').first().json.output;
const out = $input.first().json;
const kind = out.branch_kind;

let response = '';
let manualResponse = false;
let includeResponse = true;
let is_escalate_offer = false;

switch (kind) {
  case 'not_found': {
    // Normal not-found path uses not-found-error-message. The incoming-picker
    // availability branch bypasses it (annotate-incoming-picker computes the same
    // escalate_message/require_specific/is_clarification), so fall back to that node.
    // dym-probe-before-offer (rev 6): PREFER THE ANNOTATED COPY.
    // build-suggest-offer is the annotation authority for the require-specific picker; it
    // SPREADS rather than mutates, so reading not-found-error-message by name here returns
    // the PRE-annotation string and silently discards the suffixes — computed correctly,
    // rendered bare. This is the same by-name landmine the annotate-incoming-picker
    // fallback below was added for; the suffix is NOT recomputed here.
    // Source order: build-suggest-offer (annotated) -> not-found-error-message ->
    // annotate-incoming-picker. Every source carries escalate_message, require_specific and
    // is_clarification on the SAME object, so the flags below stay coherent with the text
    // regardless of which one wins. Fail-open by construction: a missing, unexecuted or
    // malformed preferred source falls through to exactly today's behaviour.
    const _annotated = (() => {
      try {
        const n = $('build-suggest-offer');
        if (!n.isExecuted) return null;
        const j = n.first().json;
        return (j && typeof j.escalate_message === 'string' && j.escalate_message) ? j : null;
      } catch (e) { return null; }
    })();
    const nfNode = $('not-found-error-message');
    const nf = _annotated
            || (nfNode.isExecuted ? nfNode.first().json : $('annotate-incoming-picker').first().json);
    response       = nf.escalate_message;
    manualResponse = !nf.require_specific;
    is_escalate_offer = !nf.is_clarification;   // offer only when it's not a clarification prompt
    break;
  }
  case 'access_choice':
    response       = $('access-level-choice-message').first().json.escalate_message;
    manualResponse = true;
    break;
  case 'demand_qty':
    response       = 'Please specify your demand quantity';
    manualResponse = true;
    break;
  case 'not_supported':
    response       = "Sorry, we don't support direct goods receive & SPO at the moment. You may ask about incoming stock for a specific product or container";
    manualResponse = true;
    break;
  case 'clarify_menu':
    response       = `I see you're ${qf.user_goal}, Let me understand more.\n\nAre you asking about any of these?\n\n- Product (List Price, Dimension)\n- Photos, Technical Specs, Cert\n- Promotion\n- Forms\n- Stock\n- Delivery order\n- Incoming\n- Catalogue, Warranty\n\nI can help with the topics listed above.`;
    manualResponse = true;
    break;
  case 'escalate_offer': {
    // #9: prefer the resolved entity's company team over the parser's access-level guess.
    const _ct = (() => { try { const g2 = $('disallowed-entity-gate'); return g2.isExecuted ? (g2.first().json.company_team || null) : null; } catch (e) { return null; } })();
    response       = `I am sorry the provided answer does not meet your requirements. Would you like me to escalate to ${_ct || qf.routing.suggested_team} team?`;
  }
    manualResponse = true;
    is_escalate_offer = true;
    break;
  case 'out_of_scope':
    response        = `Informed the user that request is out of scope and will proceed to escalate to the ${qf.routing.suggested_team} team`;
    manualResponse  = true;
    includeResponse = false;
    break;
  case 'escalation_declined':
    response          = 'Escalation declined.';   // FIXED canned reply — no LLM shaping
    manualResponse    = true;
    includeResponse   = true;
    is_escalate_offer = false;                     // → cs-offer-gate FALSE → straight to compile-current-state
    break;
  case 'offer_hold':
    // miss-company-routing rev-4: an unresolved reply on an open MULTI-company offer. The clarify ask
    // was composed upstream by offer-hold-reply (same body as clarify-company-reply); pull it by
    // reference — no LLM, no roster refetch, and compile-current-state re-persists the offer state.
    response          = (() => { try { const n = $('offer-hold-reply'); return n.isExecuted ? String(n.first().json.clarify_text || '') : ''; } catch (e) { return ''; } })();
    manualResponse    = true;
    includeResponse   = true;
    is_escalate_offer = false;                     // → cs-offer-gate FALSE → straight to compile-current-state
    break;
}

out.response          = response;
out.manualResponse    = manualResponse;
out.includeResponse   = includeResponse;
