parameters.jsCode:
// ── tier-probe-collect ───────────────────────────────────────────────────────────────────
// access-tier-ask-plan D14. Folds the N per-tier probe responses back into ONE item carrying
// `tier_availability` ({office:true, dealer:false, end_user:false}) for the ask renderer, and
// `tier_any_available` for the routing IF.
//
// PAIRING: the sub-call runs once per input item and n8n preserves input order, so probe result
// i belongs to plan item i. That is an ordering assumption, so it is made explicit and checked:
// if the counts disagree we do NOT guess an alignment — every tier falls back to "unknown"
// (null), the renderer drops the annotation entirely, and the ask still works. A wrong pairing
// would tell a customer "no promotion" about a tier that has them, which is worse than silence.
//
// AVAILABILITY is deliberately generous: a tier counts as available on `has_result === true` OR
// a non-empty answers[]. The envelope has carried both over time, and the failure direction
// matters — a false "no promotion" hides real files, while a false "has promotion" costs the
// customer one wasted pick, which is exactly today's behaviour.
const results = $input.all();
const planItems = $('tier-probe-plan').all().map(i => i.json);
const base = $('tier-gate').first().json;

const ORDER = ['dealer', 'office', 'end_user'];
let availability = null;

if (planItems.length > 0 && planItems.length === results.length && planItems[0].probe_skipped !== true) {
  availability = {};
  for (let i = 0; i < planItems.length; i++) {
    const tier = planItems[i].probe_tier;
    if (!tier) continue;
    const j = (results[i] && results[i].json) || {};
    const rows = Array.isArray(j.answers) ? j.answers : [];
    availability[tier] = j.has_result === true || rows.length > 0;
  }
}

// null availability => "we could not determine this", NOT "nothing is available". The renderer
// and the router both read it that way: no annotation, and the ask proceeds as before.
const any = availability ? Object.values(availability).some(Boolean) : true;

return [{
  json: {
    ...base,
    tier_availability: availability,
    tier_available_list: availability ? ORDER.filter(t => availability[t]) : null,
    tier_any_available: any,
    _tier_probe_count: results.length,
    _tier_probe_planned: planItems.length,
  },
}];

// ── promo-dym-plan (D18) ─────────────────────────────────────────────────────────────────
// Fans a did-you-mean offer out into ONE ITEM PER CANDIDATE so the downstream probe can ask the
// CRM, per candidate, "does this code actually have any promotion this contact may see?" before
// we suggest it.
//
// WHY per candidate and not the batched dym-probe every other domain uses: promotion rows carry
// NO product reference. Measured on a real two-product query (4 rows): every row is
// {title, fields:[Promotion, Start Date, End Date], flags}. dym-annotate's `codeOf(row)`
// attribution therefore matches nothing, and a batched probe would stamp "- no promotion" on
// EVERY candidate — the exact misdetection dym-annotate's sentinel comment calls the worst
// failure mode in that change. One deterministic call per candidate instead.
//
// Pairs entities BY CODE, never by index: dym_probe_entities and dym_candidate_codes are built by
// separate loops in dym-transform, and an index assumption between two independently-built arrays
// is the kind that holds until someone filters one of them.
const xf = $('dym-transform').first().json;
const codes = Array.isArray(xf.dym_candidate_codes) ? xf.dym_candidate_codes : [];
const ents  = Array.isArray(xf.dym_probe_entities) ? xf.dym_probe_entities : [];

const norm = (s) => String(s ?? '').trim().toLowerCase();
const byCode = new Map();
for (const e of ents) {
  const k = norm(e && (e.canonical_code || e.code || e.raw));
  if (k && !byCode.has(k)) byCode.set(k, e);
}

const items = [];
for (const c of codes) {
  const e = byCode.get(norm(c));
  if (!e) continue;                    // no entity to scope with ⇒ cannot probe it honestly
  items.push({ json: { ...xf, probe_code: c, probe_entity: e } });
}
// Never return [] — that would skip every downstream node including dym-annotate, and
// build-suggest-offer would render its un-annotated offer with no signal that the probe was
// attempted. One inert item keeps the lane intact and dym-annotate fails open.
if (items.length === 0) return [{ json: { ...xf, probe_code: null, probe_entity: null, probe_plan_empty: true } }];
return items;

