={{ (() => {
  const parser = $("Call 'sub-query-reformulator'").first().json.output;
  const aggExecuted = $('Aggregate').isExecuted;
  // S2b (promotion-picker): the customer is never asked for a level. A STATED level filters this
  // turn, intersected with entitlement (never raw — raw would leak another company's promotions).
  // Stating nothing now yields the FULL live entitlement instead of the empty intersection that
  // used to force the access-level prompt.
  const _stated   = parser.access_levels || [];
  const _entitled = aggExecuted ? $('Aggregate').first().json.name.sort() : [];
  // Q23: a stated level the contact does not hold yields an EMPTY intersection. Sending []
  // makes the CRM return nothing and the customer sees a generic "not found" for what is
  // really an entitlement problem. Fall back to their full entitlement; the gate raises the
  // notice that explains it.
  // F9: the gate's held-check is case-insensitive; this was not. A level differing only in case
  // produced NO notice (gate: held) AND an empty intersection that fell back to the FULL
  // entitlement — the customer believed they had filtered and silently got every level.
  const _lcStated = _stated.map(a => String(a).toLowerCase());
  const _inter = aggExecuted ? _entitled.filter(a => _lcStated.includes(String(a).toLowerCase())) : _stated;
  const accessLevels = _stated.length ? (_inter.length ? _inter : _entitled) : _entitled;
  return {
    message_type:      parser.message_type      ?? null,
    intent_hint:       parser.intent_hint       ?? null,
    domain_hint:       parser.domain_hint       ?? null,
    user_goal:         parser.user_goal         ?? null,
