parameters.jsCode:
// ── cs-roster-plan (brand-company-routing) ──────────────────────────────────
// One item per company to query for the CS roster. Reads the routing axes computed by
// disallowed-entity-gate (routing_companies[{company_id,company_name,brand_code,codes}]).
// No resolve this turn (gate not executed / no companies) => ONE fallback item carrying the gate's
// routing_brand when it has one => get-cs-members makes exactly today's single call (null-guarded params).
// These items ARE the pool identity: compile-current-state persists them verbatim as
// variables.routing_roster_plan and escalation-context assigns from that same pair on the bare-"yes"
// turn, so the fetch-time and assignment-time axes cannot drift apart.
const g = (() => { try { const n = $('disallowed-entity-gate'); return n.isExecuted ? n.first().json : {}; } catch (e) { return {}; } })();
const cos = (Array.isArray(g.routing_companies) && g.routing_companies.length)
  ? g.routing_companies
  : [{ company_id: null, company_name: null, brand_code: g.routing_brand || null, codes: [] }];
return cos.map((c, i) => ({ json: {
  plan_idx: i,
  company_id: c.company_id || null,
  company_name: c.company_name || null,
  brand_code: c.brand_code || null,
  codes: Array.isArray(c.codes) ? c.codes : [],
  multi_company: cos.length > 1,
  companies: cos.map(x => x.company_name).filter(Boolean),
} }));

// ── escalation-context (brand-company-routing) ──────────────────────────────
// What the escalation turn sends to sub-human-intervention: the brand/company axes, resolved
// from (1) the picked member's row in the frozen last_result_set, else (2) the roster plan the
// offer was actually fetched with (same team only — a domain switch drops the axes), else (3) a
// brand the customer stated when no roster was involved at all.
// Pool identity (rev-3 picked / rev-4 unpicked): both axes are always what the get-cs-members call
// used — a picked row's own company_id/brand_code, or the single persisted routing_roster_plan pair,
// verbatim (null stays null). Never re-derived from routing_brand or this turn's query_brands, which
// would narrow next-assignee to a pool the customer was never shown.
// Bare "yes" after a multi-company offer => both axes null (CRM resolves via contact/default).
// Pass-through: the incoming item is spread so downstream $json refs are unchanged.
const o = $('Call \'sub-query-reformulator\'').first().json.output || {};
const prev = (() => { try { const s = $('get-session-vars').first().json; return (s && s.session_vars && s.session_vars.variables) || (s && s.variables) || {}; } catch (e) { return {}; } })();
const team = (o.routing || {}).suggested_team || null;
const sameTeam = !!(prev.routing && team && prev.routing.suggested_team === team);
const picked = (o.escalation || {}).preferred_assignee_id || null;
const row = picked ? (Array.isArray(prev.last_result_set) ? prev.last_result_set : []).find(r => r && r.uuid === picked) : null;
const qb = (Array.isArray(o.query_brands) && o.query_brands.length === 1) ? String(o.query_brands[0]).toLowerCase() : null;
// miss-company-routing: a company-name reply on the confirmation turn. The parser (§2) emits
// escalation.company_pick (the CANONICAL persisted company_name) only after matching the reply
// against the companies the PERSISTED state OFFERED and finding no member match. Resolve it against
// that same persisted pool identity and send the matched row's (company_id, brand_code) VERBATIM.
// rev-4: (A) the pool is the companies actually OFFERED — routing_roster_plan when the plan is
// non-empty (the rosters shown), routing_companies ONLY when no plan exists (no roster offered) —
// never the union, so a pick can never land on a company whose roster the customer was not shown;
// (B) match order name → id → company_code (when a source ever carries it) → static alias
// (_CO_ALIASES — a STOPGAP mirror of the parser fork's map; the real source is the CRM
// companies.code column threaded through resolve-entity → disallowed-entity-gate → the plan rows),
// all case-insensitive, exactly one row. No match ⇒ cpickRow null ⇒ the arm below never fires and
// everything behaves exactly as before.
const _CO_ALIASES = { sorento: ['sorento', 'srt'], mocha: ['mocha', 'mch'], cabana: ['cabana', 'cbn'] };
const cpick = (o.escalation || {}).company_pick ? String((o.escalation || {}).company_pick).toLowerCase().trim() : null;
const cpickRow = (() => {
  if (!cpick) return null;
  const rp = Array.isArray(prev.routing_roster_plan) ? prev.routing_roster_plan : [];
  const pool = (rp.length ? rp : (Array.isArray(prev.routing_companies) ? prev.routing_companies : [])).filter(c => c && (c.company_name || c.company_id));
  const keysOf = (c) => {
    const nk = c.company_name ? String(c.company_name).toLowerCase().trim() : '';
    const ks = new Set();
    if (nk) ks.add(nk);
    if (c.company_id) ks.add(String(c.company_id).toLowerCase());
    for (const ck of [c.company_code, c.code]) if (typeof ck === 'string' && ck.trim()) ks.add(ck.toLowerCase().trim());
    for (const a of (_CO_ALIASES[nk] || [])) ks.add(a);
    return ks;
  };
  const hits = pool.filter(c => keysOf(c).has(cpick));
  const uniq = [...new Map(hits.map(c => [String(c.company_id || c.company_name).toLowerCase(), c])).values()];
  return uniq.length === 1 ? uniq[0] : null;
})();
let brand_code = null, company_id = null, company_name = null, source = 'none';
if (row) {
  company_id = row.company_id || null;
  company_name = row.company_name || null;
  brand_code = ('brand_code' in row) ? (row.brand_code || null) : ((sameTeam ? prev.routing_brand : null) || null);
  source = 'picked_member';
} else if (cpickRow) {
  // miss-company-routing: company pick — sits ABOVE the multi-company-unpicked arm (inside
  // sameTeam below) so a resolvable company reply routes instead of re-clarifying.
  company_id = cpickRow.company_id || null;
  company_name = cpickRow.company_name || null;
  brand_code = cpickRow.brand_code || null;
  source = 'company_pick';
} else if (sameTeam) {
  const rp = Array.isArray(prev.routing_roster_plan) ? prev.routing_roster_plan : [];
  if (rp.length === 1) {
    company_id = rp[0].company_id || null;
    company_name = rp[0].company_name || null;
    brand_code = rp[0].brand_code || null;
    source = company_id ? 'prior_state' : 'prior_state_no_company';
  } else if (rp.length > 1) {
    source = 'multi_company_unpicked';
  } else {
    const cos = Array.isArray(prev.routing_companies) ? prev.routing_companies : [];
    company_id = prev.routing_company || null;
    const c = cos.find(x => x && x.company_id === company_id);
    company_name = c ? (c.company_name || null) : null;
    source = company_id ? 'prior_state' : (cos.length > 1 ? 'multi_company_unpicked' : 'prior_state_no_company');
    // miss-company-routing rev-2 (captain decision 2026-08-18): NO roster was fetched for this offer
    // (routing_roster_plan empty), so there is no shown pool for a brand to disagree with — carry the
    // resolved brand from prior state instead of dropping it. next-assignee narrows to
    // brand-tagged + untagged members, so this can only refine the pool, and there is no pinned
    // pick on this arm to exclude. The roster-backed arms above keep their fetch-verbatim brand.
    if (source !== 'multi_company_unpicked') brand_code = prev.routing_brand ?? null;
  }
} else if (qb) {
  brand_code = qb;
  source = 'stated_brand';
}
return [{ json: { ...$input.first().json, brand_code, company_id, company_name, routing_source: source, team } }];

conditions.leftValue:
={{ (() => { try {
  /* miss-company-routing gate (plan §0/§1, round 3 §R3.2, rev-3 §V1, round 4 §W2/§W3) — fail-closed: ANY missing signal returns false.
     Fires only on an ANSWERED turn whose envelope shows a queried company with no answer:
     has_result true, the get-results tool is on the round-4 allowlist (LANE) AND the parser domain +
     one of that lane's routing pairs match (keeps the offer text, the roster URL and HI's team in
     lockstep), no other renderer already put an escalation offer on the turn (crossdomain-compose /
     promo-picker — ONE offer per turn, §W3), every answer carries a company_name key field (else the
     per-company presenter shape is not in play — conservative no-offer), and lookup_companies minus
     answered companies is non-empty.
     A qty-0 stock ROW is an answer (its company_name field marks the company answered) — only a company
     with ZERO rows is a miss (captain decision 2 + rev-3 captain correction: stock joins the allowlist).
     Round 4 (captain, reverses D2/D2'): promotions ×2, master products, product attachments and
     certificates join the LANE — every domain whose CRM service stamps lookup_companies now offers to
     escalate on a per-company miss. `members` stays TRUE on the two ORDERS tools ONLY, for this and
     every future row ("other than orders, all domain don't need member list").
     A row may carry MORE THAN ONE routing pair: crm_master_product_attachments_list legitimately rides
     both marketing_product (photo/drawing asks) and purchasing_certification (certificate asks) because
     the parser's deriveRouting splits product_attachment on isCert.
     The lane's `members` flag is IGNORED here — this gate decides offer/no-offer only; miss-members-gate
     reads the flag off the plan items. Derivation is kept in LOCKSTEP with miss-roster-plan. */
  const j = $json;
  if (j.has_result !== true) return false;
  const LANE = {  // round-4 allowlist (§W2) — tool ⇒ parser domain + the routing PAIR(S) it may ride (offer phrase, roster URL and HI team in lockstep) + members (true = orders-only member picker; false = plain offer, NO roster fetch). LANE == the CRM's stamp_lookup_companies set (11/11), so "all domains" is closed by construction, not by enumeration luck. MIRRORED BYTE-IDENTICAL in miss-roster-gate and miss-roster-plan — edit both together.
    'crm_order_management_orders_list':            { domain: 'order',              pairs: [['customer_service', 'order_enquiries']],                                                        members: true },
    'crm_order_management_orders_by_product_list': { domain: 'order',              pairs: [['customer_service', 'order_enquiries']],                                                        members: true },
    'crm_incoming_stock_list':                     { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_incoming_stock_by_product':               { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_incoming_stock_shipments':                { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_inventory_stock_balance_list':            { domain: 'inventory',          pairs: [['warehouse', 'general_enquiries']],                                                             members: false },
    'crm_marketing_promotions_list':               { domain: 'promotion',          pairs: [['marketing_promotion', 'general_enquiries']],                                                   members: false },
    'crm_marketing_promotion_products_list':       { domain: 'promotion',          pairs: [['marketing_promotion', 'general_enquiries']],                                                   members: false },
    'crm_master_products_list':                    { domain: 'master_products',    pairs: [['purchasing_product', 'general_enquiries']],                                                    members: false },
    'crm_master_product_attachments_list':         { domain: 'product_attachment', pairs: [['marketing_product', 'general_enquiries'], ['purchasing_certification', 'general_enquiries']],   members: false },
    'crm_certificates_list':                       { domain: 'product_attachment', pairs: [['purchasing_certification', 'general_enquiries']],                                              members: false },
  };
  const tool = String((($('tool-filter').first().json) || {}).name || '').trim();
  // round-3 rev-2 (F-R3-4): membership test via Object.keys — the n8n expression sandbox rejects the hasOwnProperty
  // form (Object.<forbidden-member>.hasOwnProperty.call, LESSONS #45) at parse time; NOT catchable by this try/catch.
  const lane = (tool && Object.keys(LANE).includes(tool)) ? LANE[tool] : null;
  if (!lane) return false;
  const o = $('Call \'sub-query-reformulator\'').first().json.output || {};
  if (o.domain_hint !== lane.domain) return false;
  const r = o.routing || {};
  if (!lane.pairs.some(p => p[0] === r.suggested_team && p[1] === r.suggested_agent)) return false;
  // one offer per turn: crossdomain-compose appends its OWN frozen phrase when crossdomain-render produced a block — yield to it
  { const xr = $('crossdomain-render'); if (xr.isExecuted && ((((xr.first().json) || {})._xdBlock) || {}).any === true) return false; }
  // ROUND 4 · one offer per turn (a) — GENERIC: the rendered reply already carries the frozen
  // phrase (promo-picker's _promo_unmatched / strict-miss / brand-gate arms write their own, and any
  // future renderer that does the same is covered without another leg). Inert on the round-2/3
  // lanes: output-structurer never writes the phrase, and crossdomain-compose runs AFTER ccs.
  if (/would you like me to escalate/i.test(String(j.response || ''))) return false;
  // ROUND 4 · one offer per turn (b) — promo-picker rebuilt or short-circuited the reply. Marker
  // keys ride on promo-picker's own item; read them by node reference (central-exchange unwraps
  // `input.output` on the wrapped shape and would drop them).
  { const pp = $('promo-picker'); if (pp.isExecuted) { const p = pp.first().json || {};
      if (p._brand_gate_closed === true || p._promo_notfound || p._promo_unmatched
          || p._promo_pick || p._promo_picker_shape) return false; } }
  const lc = Array.isArray(j.lookup_companies) ? j.lookup_companies : [];
  if (!lc.length) return false;
  const ans = Array.isArray(j.answers) ? j.answers : [];
  if (!ans.length) return false;
  const hit = [];
  for (const a of ans) {
    const f = (a && Array.isArray(a.fields)) ? a.fields.find(x => x && x.key === 'company_name' && x.value) : null;
    if (!f) return false;
    hit.push(String(f.value).toLowerCase().trim());
  }
  return lc.some(c => c && c.name && !hit.includes(String(c.name).toLowerCase().trim()));
} catch (e) { return false; } })() }}

parameters.jsCode:
// ── miss-roster-plan (miss-company-routing, round 4) ────────────────────────
// One item per MISS company on an ANSWERED turn that passed miss-roster-gate — orders, incoming,
// stock, promotions (list + promotion products), master products, product attachments and
// certificates (round 4, captain: "all domain also need to behave like this, if no record, then
// offer to escalate"; the LANE below is exactly the CRM's stamp_lookup_companies set, 11/11): a
// company the envelope says was queried (lookup_companies) but that contributed no answer (no
// answers[].fields[key='company_name'] naming it). miss-roster-gate has already verified the shape
// (has_result, lane domain + one of the lane's routing pairs, no competing offer on the turn, EVERY
// answer labelled with a company_name key field, non-empty miss set) with the SAME derivation —
// keep the two in lockstep: an empty result here would starve the happy lane of its item, so the
// impossible-empty case degrades to ONE null-company sentinel item (members:false — a sentinel must
// NEVER fetch a roster; miss-members-gate routes it FALSE and build-miss-member-offer passes the
// envelope through, turn byte-identical). Every real item carries the lane's `members` flag
// (true = orders-only member picker via get-cs-members-miss; false = plain offer, NO roster fetch —
// miss-members-gate reads it off $json) and `team` — the team the frozen phrase names and the team
// HI will actually assign to. ROUND 4: `team` is stamped from the PARSER's actual suggested_team,
// not from a hard-coded row field, because a row may carry TWO routing pairs
// (crm_master_product_attachments_list rides marketing_product for photo asks and
// purchasing_certification for certificate asks) — a hard-coded team would tell a certificates ask
// "marketing_product team". The gate has already proven the parser's pair is one of the row's, so
// the parser value is always in-lane. Item shape mirrors cs-roster-plan so downstream consumers
// (build-miss-member-offer, the ccs persistence hunk, escalation-context) treat the two plans
// identically; brand_code is looked up from disallowed-entity-gate's routing_companies entry for
// the company (null when absent — the roster call then runs company-only, same pool the CRM would
// assign from).
const env = $('central-exchange').first().json;
  const LANE = {  // round-4 allowlist (§W2) — tool ⇒ parser domain + the routing PAIR(S) it may ride (offer phrase, roster URL and HI team in lockstep) + members (true = orders-only member picker; false = plain offer, NO roster fetch). LANE == the CRM's stamp_lookup_companies set (11/11), so "all domains" is closed by construction, not by enumeration luck. MIRRORED BYTE-IDENTICAL in miss-roster-gate and miss-roster-plan — edit both together.
    'crm_order_management_orders_list':            { domain: 'order',              pairs: [['customer_service', 'order_enquiries']],                                                        members: true },
    'crm_order_management_orders_by_product_list': { domain: 'order',              pairs: [['customer_service', 'order_enquiries']],                                                        members: true },
    'crm_incoming_stock_list':                     { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_incoming_stock_by_product':               { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_incoming_stock_shipments':                { domain: 'incoming',           pairs: [['purchasing', 'incoming_stock_enquiries']],                                                     members: false },
    'crm_inventory_stock_balance_list':            { domain: 'inventory',          pairs: [['warehouse', 'general_enquiries']],                                                             members: false },
    'crm_marketing_promotions_list':               { domain: 'promotion',          pairs: [['marketing_promotion', 'general_enquiries']],                                                   members: false },
    'crm_marketing_promotion_products_list':       { domain: 'promotion',          pairs: [['marketing_promotion', 'general_enquiries']],                                                   members: false },
    'crm_master_products_list':                    { domain: 'master_products',    pairs: [['purchasing_product', 'general_enquiries']],                                                    members: false },
    'crm_master_product_attachments_list':         { domain: 'product_attachment', pairs: [['marketing_product', 'general_enquiries'], ['purchasing_certification', 'general_enquiries']],   members: false },
    'crm_certificates_list':                       { domain: 'product_attachment', pairs: [['purchasing_certification', 'general_enquiries']],                                              members: false },
  };
const tool = String((($('tool-filter').first().json) || {}).name || '').trim();
const lane = (tool && Object.keys(LANE).includes(tool)) ? LANE[tool] : null;  // fail-closed: unknown lane ⇒ members:false, team:null (plain path, never a roster fetch)
// ROUND 4: the phrase/roster/HI team comes from the parser, which the gate proved is one of the
// lane's pairs. Fail-closed: unreadable routing ⇒ null ⇒ ccs's _mcTeamP falls back to the parser's
// own suggested_team (same value) and, failing that, 'customer_service'.
const _team = (() => { try { const o = $("Call 'sub-query-reformulator'").first().json.output || {}; return String(((o.routing) || {}).suggested_team || '').trim() || null; } catch (e) { return null; } })();
const lc = Array.isArray(env.lookup_companies) ? env.lookup_companies : [];
const ans = Array.isArray(env.answers) ? env.answers : [];
const answered = new Set();
for (const a of ans) {
  const f = (a && Array.isArray(a.fields)) ? a.fields.find(x => x && x.key === 'company_name' && x.value) : null;
  if (f) answered.add(String(f.value).toLowerCase().trim());
}
const g = (() => { try { const n = $('disallowed-entity-gate'); return n.isExecuted ? n.first().json : {}; } catch (e) { return {}; } })();
const rc = Array.isArray(g.routing_companies) ? g.routing_companies : [];
const miss = lc.filter(c => c && c.name && !answered.has(String(c.name).toLowerCase().trim()));
if (!miss.length) {
  // gate/plan divergence sentinel — see header. build-miss-member-offer drops null-company items.
  return [{ json: { plan_idx: 0, company_id: null, company_name: null, brand_code: null, codes: [], multi_company: false, companies: [], team: null, members: false, _miss_plan_empty: true } }];
}
return miss.map((c, i) => {
  const m = rc.find(x => x && ((x.company_id && c.id && x.company_id === c.id) || (x.company_name && c.name && String(x.company_name).toLowerCase().trim() === String(c.name).toLowerCase().trim()))) || null;
  return { json: {
    plan_idx: i,
    company_id: c.id || null,
    company_name: c.name || null,
    brand_code: (m && m.brand_code) || null,
    codes: (m && Array.isArray(m.codes)) ? m.codes : [],
    multi_company: miss.length > 1,
    companies: miss.map(x => x.name).filter(Boolean),
    team: lane ? _team : null,
    members: lane ? lane.members === true : false,
  } };
});

// ── build-miss-member-offer (miss-company-routing, rev-3) ───────────────────
// TWO arms on an ANSWERED turn that missed a company (captain case A: keep the found results +
// the presenter's miss line, then offer escalation). MEMBERS arm (orders lane, members:true —
// reached via miss-members-gate TRUE → get-cs-members-miss): renders the miss company's member
// picker; input is one fullResponse item per miss-roster-plan item (index-aligned, onError
// degrades to an error item = empty roster). PLAIN arm (rev-3; incoming + stock lanes,
// members:false — reached DIRECTLY from miss-members-gate FALSE, no roster was fetched): no
// picker, no rows — just the envelope + miss_plain_offer + the plan identity, and
// compile-current-state appends the frozen phrase. (The old "order turn" header was stale —
// F-R3-2.) Mirrors build-cs-member-offer's roster parsing / dedupe / row shape
// (cs_last_result_set-shaped rows incl. company_id/company_name/brand_code/company_ids/companies)
// so the parser's Δ3 pick arm and escalation-context treat these rows identically to an ordinary
// member offer. Numbering CONTINUES after the reply's existing numbered blocks (the envelope
// answers are persisted as last_result_set rows 1..N by ccs's compressed view; "a stray 2 must
// still pick" the right row): base = max(numbers printed in the response text, answers.length).
// rev-3 rendering: plain `n. Name` lines; >1 miss company ⇒ bold `*Company:*` group headers and a
// "reply with the company name (*A* / *B*)" closing sentence instead of the yes-sentence.
// Output: the central-exchange envelope item passed through (the miss lane sits between
// central-exchange and dym-transform-partial, which appends to whatever item it receives), plus
// miss_member_offer / miss_member_rows / miss_offer_text / miss_roster_plan when ≥1 member was
// found. Zero members from every miss company — or ANY surprise — ⇒ envelope passthrough exactly
// (turn byte-identical; ccs's merge hunk keys on miss_member_offer === true AND non-empty rows).
const env = $('central-exchange').first().json;
const pass = [{ json: { ...env } }];
try {
  const plan = (() => { try { return $('miss-roster-plan').all().map(i => i.json); } catch (e) { return []; } })();
  // rev-3 PLAIN arm (§V2/§V4) — every non-sentinel plan item says members === false (incoming/
  // stock): emit the envelope + miss_plain_offer:true + miss_roster_plan (plan identity incl. the
  // lane team for ccs's frozen phrase). NO miss_member_offer, NO miss_member_rows, NO
  // miss_offer_text — pool = ALL miss companies (no roster was shown, so no intersection rule).
  // A plan item MISSING the flag falls through to the roster parse below, which yields [] members
  // on plan-item input ⇒ envelope passthrough (fail-closed: never a broken turn, never a surprise
  // picker). Zero non-sentinel items (the _miss_plan_empty sentinel) ⇒ same passthrough.
  const real = plan.filter(p => p && p._miss_plan_empty !== true && (p.company_id || p.company_name));
  if (real.length && real.every(p => p.members === false)) {
    const planOut = real.map((p, i) => ({ plan_idx: (p.plan_idx != null) ? p.plan_idx : i, company_id: p.company_id || null, company_name: p.company_name || null, brand_code: p.brand_code || null, team: (typeof p.team === 'string' && p.team) ? p.team : null }));
    return [{ json: { ...env, miss_plain_offer: true, miss_roster_plan: planOut } }];
  }
  const resp = $input.all().map(i => i.json);
  const rosterAt = (i) => {
    const r = resp[i];
    if (!r || r.error) return [];                              // onError item ⇒ empty roster for that company
    if (Array.isArray(r.body)) return r.body;                  // fullResponse shape
    if (Array.isArray(r)) return r;                            // legacy: one item, json=array
    return [];
  };
  const isRow = (m) => m && m.user_id && m.respond_user_id;   // respond.io assign can't reach members without respond_user_id
  const members = [];
  const seen = new Map();
  plan.forEach((p, i) => {
    // fail-closed: a real miss company always carries id+name (from lookup_companies); the
    // empty-plan sentinel and any degenerate item contribute nothing.
    if (!p || p._miss_plan_empty === true || (!p.company_id && !p.company_name)) return;
    for (const m of rosterAt(i).filter(isRow)) {
      const prev = seen.get(m.user_id);
      if (prev) {   // dedupe by user_id across companies; membership is a set (build-cs-member-offer rev-6)
        if (p.company_name && !prev.companies.includes(p.company_name)) prev.companies.push(p.company_name);
        if (!prev.company_ids.includes(p.company_id || null)) prev.company_ids.push(p.company_id || null);
        continue;
      }
      const row = { ...m, company_id: p.company_id || null, company_name: p.company_name || null, brand_code: p.brand_code || null, companies: p.company_name ? [p.company_name] : [], company_ids: [p.company_id || null] };
      seen.set(m.user_id, row);
      members.push(row);
    }
  });
  if (!members.length) return pass;
  // numbering base: continue after the reply's existing numbered blocks
  const nums = String(env.response || '').match(/^\s*(\d+)\.\s/gm) || [];
  const maxNum = nums.reduce((a, s) => Math.max(a, parseInt(s, 10) || 0), 0);
  const base = Math.max(maxNum, Array.isArray(env.answers) ? env.answers.length : 0);
  const rows = members.map((m, i) => ({
    idx: base + i + 1, label: m.name, uuid: m.user_id, respond_user_id: m.respond_user_id,
    company_id: m.company_id || null, company_name: m.company_name || null, brand_code: m.brand_code || null,
    company_ids: Array.isArray(m.company_ids) ? m.company_ids : [m.company_id || null],
    companies: Array.isArray(m.companies) ? m.companies : (m.company_name ? [m.company_name] : []),
  }));
  // rev-5 intersection rule: persist only the plan items whose company actually contributed a
  // member — the pool identity must describe the roster SHOWN, not the calls made.
  const shown = new Set();
  for (const r of rows) for (const id of (Array.isArray(r.company_ids) ? r.company_ids : [])) shown.add(id || null);
  const used = plan.filter(p => p && !p._miss_plan_empty && shown.has(p.company_id || null));
  // rev-3 (captain copy decisions): member lines are plain `n. Name` everywhere — no per-member
  // `(Company)` suffix. ONE miss company ⇒ flat list + the original yes-sentence. MORE than one miss
  // company ⇒ grouped under bold `*Company:*` headers (a shared member keeps ONE number and is listed
  // under each group it belongs to — build-cs-member-offer's rev-6 rule) and the closing sentence asks
  // for the company name (bold, offer order) — a bare "yes" cannot assign on a multi-company pool.
  // `used` (the plan items that contributed a member) is the SAME signal compile-current-state's miss
  // arm keys its phrase/axes on (_mcPlan.length === 1), so wording and pool identity stay in lockstep.
  const multi = used.length > 1;
  let lines;
  if (!multi) {
    lines = rows.map(r => `${r.idx}. ${r.label}`).join('\n');
  } else {
    const inCo = (r, p) => (Array.isArray(r.company_ids) ? r.company_ids : [r.company_id || null]).some(id => (id || null) === (p.company_id || null));
    const grouped = [];
    for (const p of used) {
      const group = rows.filter(r => inCo(r, p));
      if (!group.length) continue;
      grouped.push(`*${p.company_name || 'Other'}:*`);
      for (const r of group) grouped.push(`${r.idx}. ${r.label}`);
    }
    lines = grouped.join('\n');
  }
  const close = multi
    ? `If you have no preference, reply with the company name (${used.map(p => `*${p.company_name || 'Other'}*`).join(' / ')}) and we'll assign accordingly.`
    : `If you have no preference, just reply 'yes' and we'll assign automatically.`;
  const offer = `Please choose who to route to (reply with the number):\n${lines}\n\n${close}`;
  return [{ json: { ...env, miss_member_offer: true, miss_member_rows: rows, miss_offer_text: offer, miss_roster_plan: used } }];
} catch (e) {
  return pass;   // fail-closed: any surprise leaves the turn untouched
}

// ── clarify-company-reply / offer-hold-reply (miss-company-routing; ONE body deployed to BOTH nodes) ──
// A MULTI-company offer is open and this reply did not resolve it — either a bare "yes" (case B:
// escalation-context resolved routing_source === 'multi_company_unpicked' and clarify-company-gate
// diverted the HI call to `clarify-company-reply`; silently assigning would round-robin a pool the
// customer never chose), or (rev-4, node `offer-hold-reply`) the parser stayed in the offer but
// resolved nothing (escalation.offer_hold / member_reprompt on a multi pool — junk, out-of-range
// number, ambiguous name, small talk): offer-hold-gate routes here BEFORE If10 so neither the
// fallback member re-offer nor the clarification LLM can replace the shown pool.
// This node only COMPOSES the clarify ask; it sends nothing itself: compile-current-state — which
// runs AFTER this branch (case B: measured node order, exec 12836119; offer-hold: linear chain
// offer-hold-reply → tag-offer-hold → escalate-catalog → cs-offer-gate → ccs) — sees this node
// executed, puts clarify_text on the EXISTING guarded send path (crossdomain-compose →
// sorento-sub-respond-sendmsg-respond2, is_test=true on the clone) and RE-persists the prior offer
// state (frozen phrase + rows + roster plan + companies + selection_context) so the next reply — a
// number, a member name, or a company name/code (parser company_pick) — still resolves against
// the same offer. Only an explicit decline or a brand-new business query clears the offer.
// Copy (rev-4 captain decision + rev-3 plain branch): company names bold in the lead (WhatsApp
// single *asterisks*); codes (SRT / MCH / CBN) are accepted silently either way. When the open
// offer showed a MEMBER PICKER (prev.selection_context === 'member_offer') the ask keeps "a
// number, a name, or the company (X / Y)" byte-identical; when NO picker was shown (plain-offer
// both-miss, not-found both-miss — selection_context never armed) there are no numbers or names
// to reply with, so the ask is company-only (F-R3-1 closed by copy, option (c)). offer-hold-gate
// only fires with selection_context === 'member_offer', so offer-hold-reply always takes the
// member branch — no behaviour change on that node.
const prev = (() => { try { const s = $('get-session-vars').first().json; return (s && s.session_vars && s.session_vars.variables) || (s && s.variables) || {}; } catch (e) { return {}; } })();
const pools = (Array.isArray(prev.routing_roster_plan) && prev.routing_roster_plan.length)
  ? prev.routing_roster_plan
  : (Array.isArray(prev.routing_companies) ? prev.routing_companies : []);
const names = [...new Set(pools.map(p => p && p.company_name).filter(Boolean))];
const joined = names.length > 1 ? `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}` : (names[0] || '');
const list = names.length ? names.join(' / ') : 'the companies listed';
const bold = names.map(n => `*${n}*`);
const joinedBold = bold.length > 1 ? `${bold.slice(0, -1).join(', ')} and ${bold[bold.length - 1]}` : (bold[0] || '');
const lead = names.length === 2 ? `Both ${joinedBold} teams are listed`
  : (joinedBold ? `${joinedBold} teams are listed` : `More than one team is listed`);
const clarify_text = prev.selection_context === 'member_offer'
  ? `${lead} — reply a number, a name, or the company (${list}) and I'll assign automatically.`
  : `${lead} — reply with the company (${list}) and I'll assign automatically.`;
return [{ json: { ...$input.first().json, clarify_company: true, clarify_text } }];

